package com.wingedsheep.engine.scenarios

import com.wingedsheep.engine.support.GameTestDriver
import com.wingedsheep.engine.support.TestCards
import com.wingedsheep.sdk.core.Color
import com.wingedsheep.sdk.core.Step
import com.wingedsheep.sdk.model.Deck
import io.kotest.core.spec.style.FunSpec
import io.kotest.matchers.shouldBe

/**
 * Primal Might (M21 #197) — {X}{G} Sorcery.
 *
 * "Target creature you control gets +X/+X until end of turn. Then it fights up to one target
 *  creature you don't control."
 *
 * Generated by mtgish-tooling, whose target recovery read the IR's `ControlledByAPlayer(Other(You))`
 * as a bare `You` and rendered `.youControl()` on the fight target — so the pump-and-fight could only
 * be aimed at the caster's own creatures.
 */
class PrimalMightScenarioTest : FunSpec({

    fun newDriver(): GameTestDriver {
        val driver = GameTestDriver()
        driver.registerCards(TestCards.all)
        driver.initMirrorMatch(Deck.of("Forest" to 40), skipMulligans = true, startingPlayer = 0)
        driver.passPriorityUntil(Step.PRECOMBAT_MAIN)
        return driver
    }

    test("the fight target must be a creature you don't control") {
        val driver = newDriver()
        val yours = driver.putCreatureOnBattlefield(driver.player1, "Grizzly Bears") // 2/2
        val alsoYours = driver.putCreatureOnBattlefield(driver.player1, "Minotaur Warrior") // 2/3

        val might = driver.putCardInHand(driver.player1, "Primal Might")
        driver.giveMana(driver.player1, Color.GREEN, 3)
        driver.castXSpell(driver.player1, might, xValue = 2, targets = listOf(yours, alsoYours))
            .isSuccess shouldBe false
    }

    test("X=2 pumps your creature to 4/4, which then kills the opponent's 2/3 in the fight") {
        val driver = newDriver()
        val yours = driver.putCreatureOnBattlefield(driver.player1, "Grizzly Bears") // 2/2 -> 4/4
        val theirs = driver.putCreatureOnBattlefield(driver.player2, "Minotaur Warrior") // 2/3

        val might = driver.putCardInHand(driver.player1, "Primal Might")
        driver.giveMana(driver.player1, Color.GREEN, 3)
        driver.castXSpell(driver.player1, might, xValue = 2, targets = listOf(yours, theirs))
            .isSuccess shouldBe true
        driver.bothPass()

        // The +2/+2 lands before the fight, so a 4/4 kills the 2/3 and survives the 2 back.
        driver.findPermanent(driver.player2, "Minotaur Warrior") shouldBe null
        driver.findPermanent(driver.player1, "Grizzly Bears") shouldBe yours
    }
})
